"""End-to-end test for chunk_markdown: full document content in, chunks out."""

import json

import chunker


class FakeTokenizer:
    def encode(self, text, add_special_tokens=False):
        return list(range(len(text.split())))


def write_chunks_file(
    content: str,
    output_path: str,
    max_tokens: int = 500,
) -> list[dict]:
    """Gera um arquivo JSON com os chunks extraídos do conteúdo."""
    chunks = chunker.chunk_markdown(
        content,
        FakeTokenizer(),
        max_tokens=max_tokens,
    )
    with open(output_path, "w", encoding="utf-8") as f:
        json.dump(chunks, f, ensure_ascii=False, indent=2)
    return chunks


def test_full_document_produces_chunks():
    chunks = chunker.chunk_markdown(DOC_CONTENT, FakeTokenizer(), max_tokens=320)

    assert isinstance(chunks, list)
    assert len(chunks) > 0

    for chunk in chunks:
        assert set(chunk.keys()) == {"secao", "content", "n_tokens"}
        assert isinstance(chunk["secao"], str) and chunk["secao"]
        assert isinstance(chunk["content"], str) and chunk["content"]
        assert isinstance(chunk["n_tokens"], int) and chunk["n_tokens"] > 0

    sections = [c["secao"] for c in chunks]
    assert "Biografia de Thiago Magela Rodrigues Dias" in sections
    assert (
        "Biografia de Thiago Magela Rodrigues Dias"
        " > Artigos Científicos Publicados em Anais de Eventos Científicos"
        in sections
    )


def test_chunks_reassemble_full_document():
    chunks = chunker.chunk_markdown(DOC_CONTENT, FakeTokenizer(), max_tokens=500)

    for section in set(c["secao"] for c in chunks):
        contents = [c["content"] for c in chunks if c["secao"] == section]
        joined = "\n\n".join(contents)
        assert isinstance(joined, str) and joined


def test_write_chunks_file_generates_valid_json(tmp_path):
    output = tmp_path / "chunks.json"
    chunks = write_chunks_file(DOC_CONTENT, str(output), max_tokens=500)

    assert output.exists()
    assert output.stat().st_size > 0

    with open(output, "r", encoding="utf-8") as f:
        loaded = json.load(f)

    assert loaded == chunks
    assert isinstance(loaded, list)
    assert all(set(c.keys()) == {"secao", "content", "n_tokens"} for c in loaded)


